reto.codigo:
const cuadrado = (n) => n * n;
function sumaCuadrados(lista) {
  let t = 0;
  for (const n of lista) {
    t = t + cuadrado(n);
  }
  return t;
}
console.log(sumaCuadrados([1, 2, 3]));

